import{z as n,x as B,o as t,c as p,q as i,j as s,D as e,d as E,s as d,S as l,b as r}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"分布式死锁","description":"","frontmatter":{"title":"分布式死锁","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/distributed-deadlock.md","filePath":"cs/distributed-deadlock.md","lastUpdated":1791413859000}'),A={name:"cs/distributed-deadlock.md"};function T(C,a,m,b,u,D){const o=B("Mermaid");return t(),p("div",null,[a[2]||(a[2]=i('<h1 id="分布式死锁" tabindex="-1">分布式死锁 <a class="header-anchor" href="#分布式死锁" aria-label="Permalink to &quot;分布式死锁&quot;">​</a></h1><div class="epigraph"><p>等待边跨节点时，局部无环仍可能全局有环。检测靠探测或超时，预防靠全局戳与锁序。</p><footer>—— 据 Obermarck 探测算法；Gray and Reuter；单机 wait-for 课的网络扩展</footer></div><p><a href="/cs/spanner-truetime">上一课</a>跨 Paxos 组 2PC。本课不 commit wait。缺口是锁等待图跨机器：片 A 上 T1 等 T2，片 B 上 T2 等 T1，各节点 DFS 看不见环。主干单库 WFG。进阶：边追逐（probe）、中心检测器、或超时。Calvin 定序加锁按键序可避免环。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>探测：等待者发 probe 沿等待边走，带着事务 id 路径，回到自己则环。虚假探测、探测风暴是代价。中心：各节点汇报边，中心求环——单点与延迟。超时：假阳性。缺口是<strong>与 2PC 嵌套</strong>：prepared 等协调器，协调器等锁，图更怪，要包含协议边。</p><p>wait-die 用全局时间戳预防，跨节点仍成立若戳全局。伤口等待同理。</p><p><span class="marginnote">Obermarck 分布式死锁检测。Gray and Reuter。本课不实现完整 probe 包格式。</span></p><p><span class="marginnote">术语翻译：wait-for graph（等待图）就是「谁在等谁」的一张有向图——箭头从等待者指向持锁者。死锁 = 图上有环：T1 等 T2、T2 等 T1，谁也不肯先动。单机时一张图画完就能找环；分布式的新麻烦是这张图被切成了好几片，每片只看见自己那部分箭头。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>工程常超时+死锁日志，精确检测留给锁量小的系统。Spanner 类：锁在组长，跨组 2PC 超时。Percolator：锁在行上，客户端轮询超时清理。</p><p>锁序：对分片 id 排序加锁，预防环，可能增加延迟（多一轮）。</p>',11)),(t(),s(l,null,{default:e(()=>[d(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20T1%5B%22T1%20%E5%9C%A8%E7%89%87%20A%20%E7%AD%89%20T2%22%5D%20--%3E%20PR%5B%22probe%20%E6%B2%BF%E8%BE%B9%22%5D%0A%20%20T2%5B%22T2%20%E5%9C%A8%E7%89%87%20B%20%E7%AD%89%20T1%22%5D%20--%3E%20PR%0A%20%20PR%20--%3E%20CY%5B%22%E5%9B%9E%E5%88%B0%E8%B5%B7%E7%82%B9%E5%88%99%E6%AD%BB%E9%94%81%22%5D%0A%20%20ALT%5B%22%E8%B6%85%E6%97%B6%20%2F%20%E5%85%A8%E5%B1%80%E6%88%B3%E9%A2%84%E9%98%B2%22%5D%20--%3E%20AB%5B%22abort%20%E4%B8%80%E4%BE%A7%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[E("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,"牺牲者回滚要跨片 undo，2PC abort。检测延迟加大锁持有，放大死锁概率——恶性循环，故预防或短超时常见。",-1)),a[5]||(a[5]=r("p",null,"与 MVCC：无锁等待则无这类环，abort 来自冲突。混合系统两套。",-1)),(t(),s(l,null,{default:e(()=>[d(o,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20SHARD_A%5B%22%E7%89%87%20A%20%E7%9A%84%E6%9C%AC%E5%9C%B0%E8%A7%86%E5%9B%BE%22%5D%0A%20%20%20%20L1%5B%22T1%20%E7%AD%89%20T2%EF%BC%88T2%20%E7%9A%84%E9%94%81%E5%9C%A8%E7%89%87%20B%EF%BC%89%22%5D%0A%20%20end%0A%20%20subgraph%20SHARD_B%5B%22%E7%89%87%20B%20%E7%9A%84%E6%9C%AC%E5%9C%B0%E8%A7%86%E5%9B%BE%22%5D%0A%20%20%20%20L2%5B%22T2%20%E7%AD%89%20T1%EF%BC%88T1%20%E7%9A%84%E9%94%81%E5%9C%A8%E7%89%87%20A%EF%BC%89%22%5D%0A%20%20end%0A%20%20L1%20--%3E%7C%22probe%20%E8%B7%A8%E7%BD%91%22%7C%20L2%0A%20%20L2%20--%3E%7C%22probe%20%E8%B7%A8%E7%BD%91%22%7C%20L1%0A%20%20BOTH%5B%22%E7%89%87%20A%20%E5%8F%AA%E8%A7%81%E4%B8%80%E6%9D%A1%E8%BE%B9%EF%BC%9A%E6%97%A0%E7%8E%AF%EF%BC%9B%E7%89%87%20B%20%E5%90%8C%E6%A0%B7%EF%BC%9A%E6%97%A0%E7%8E%AF%22%5D%20-.-%3E%7C%22%E6%8B%BC%E8%B5%B7%E6%9D%A5%E6%89%8D%E6%98%AF%E7%8E%AF%22%7C%20CYC%5B%22%E5%85%A8%E5%B1%80%E6%AD%BB%E9%94%81%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=i('<p>这张图回答「为什么各节点自查都报平安，系统却卡死了」：每个片的 DFS 只看见「一条边」，单条边不成环；环的另一半藏在别的机器上。探测算法做的事就是把这条边追出去——probe 沿等待边跨网跳，路径记录回到发起者时环才现形。数字实例：环长 4 时，probe 要跨 3 个节点、往返 3 轮网络延迟才能确认，期间所有涉事锁都继续被按住。</p><p><span class="marginnote">数字实例看 wait-die：用时间戳当年龄，ts 小者老。老事务 T1（ts=50）请求年轻事务 T2（ts=100）持有的锁 → T1 等；反过来 T2 请求 T1 的锁 → T2 自杀（die）重启。因为重启后 ts 不变、永远是「年轻」，它不会积累年龄去跟人抢，环就永远凑不齐——预防的代价是年轻者可能白死几回。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲一致性哈希环。也不把死锁当拜占庭。网络分区造成的「永远等」是故障检测器，不是环。</p><p>后课默认：跨片锁要超时或探测或全局序。一致性哈希在数据库：环上放片，减再平衡搬家。</p><p>分布式 WFG 的边是 RPC，延迟让检测本身过期。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>全局环需探测、中心图或超时；预防用全局戳或锁序。</li><li>2PC prepared 状态必须进等待模型。</li><li>一致性哈希在数据库下一课。</li><li>出处：Obermarck；Gray and Reuter；wait-die。</li></ul>',8))])}const _=n(A,[["render",T]]);export{h as __pageData,_ as default};
